%[text] # Principal Component Analysis Using the SVD
%[text] This live script shows how principal component analysis (PCA) can be carried out directly from the singular value decomposition (SVD) of a centered data matrix.
%[text] The main example uses synthetic three-dimensional data that lies close to a tilted plane, so the reduction from a three-dimensional feature space to a two-dimensional feature space is easy to see geometrically.
%[text:tableOfContents]{"heading":"Contents"}
%[text] - connect PCA to the singular value decomposition
%[text] - build a synthetic data set in three dimensions
%[text] - visualize the principal directions and the reduced coordinates
%[text] - quantify explained variance and reconstruction error \
format compact
format shortG

%%
%[text] ## PCA from the SVD
%[text] Suppose the rows of $X$ are observations and the columns are features. After centering the columns, compute the economy SVD
%[text] $X\_c = U \\Sigma V^T$.
%[text] The columns of $V$ are the principal directions, the principal-component coordinates are $X\_cV = U \\Sigma$, and the variance captured by component $i$ is proportional to $\\sigma\_i^2$.
%[text] In other words, PCA is a geometric interpretation of the SVD of the centered data matrix.

%%
%[text] ## Create a Synthetic 3-D Data Set
%[text] The synthetic cloud starts as an ellipse in a two-dimensional latent plane with a small amount of thickness in the third direction, then the cloud is rotated and shifted into a three-dimensional feature space.
rng(7)

n = 450;
theta = linspace(0, 2*pi, n).';
majorRadius = 3.2 + 0.25*randn(n,1);
minorRadius = 1.4 + 0.12*randn(n,1);
thickness = 0.18*randn(n,1);

latentPlaneData = [
    majorRadius .* cos(theta), ...
    minorRadius .* sin(theta), ...
    thickness
];

R = rotationFromEuler(28, -22, 35);
featureOffset = [1.8 -1.2 0.9];
X = latentPlaneData * R.' + featureOffset;

mu = mean(X, 1);
Xc = X - mu;
[U,S,V] = svd(Xc, 'econ');
scores = U * S;

singularValues = diag(S);
componentVariance = singularValues.^2 / (n - 1);
explained = 100 * componentVariance / sum(componentVariance);
cumulativeExplained = cumsum(explained);
rank2Scores = scores(:,1:2);
Xrank2 = rank2Scores * V(:,1:2).' + mu;

componentSummary = table((1:3).', singularValues, explained, cumulativeExplained, ... %[output:group:4d1dc43a] %[output:59bb605f]
    'VariableNames', ["Component","SingularValue","ExplainedPercent","CumulativePercent"]) %[output:group:4d1dc43a] %[output:59bb605f]

%%
%[text] ## Geometric View of the Reduction
%[text] The left tile shows the observations in the original three-dimensional feature space together with the principal directions.
%[text] The middle tile rotates into principal-component coordinates, where the third axis is visibly much smaller.
%[text] The right tile keeps only the first two principal coordinates, which is the reduced two-dimensional representation.
plotColors = turbo(n);
axisLimits = paddedLimits([X; Xrank2], 0.12);
pcAxisScale = 1.2 * std(scores(:,1));

tiledlayout(1,3) %[output:15df5549]

nexttile %[output:15df5549]
scatter3(X(:,1), X(:,2), X(:,3), 22, plotColors, 'filled') %[output:15df5549]
hold on %[output:15df5549]
quiver3(mu(1), mu(2), mu(3), pcAxisScale*V(1,1), pcAxisScale*V(2,1), pcAxisScale*V(3,1), ... %[output:15df5549]
    0, 'LineWidth', 2.2, 'Color', [0.85 0.33 0.10]) %[output:15df5549]
quiver3(mu(1), mu(2), mu(3), pcAxisScale*V(1,2), pcAxisScale*V(2,2), pcAxisScale*V(3,2), ... %[output:15df5549]
    0, 'LineWidth', 2.2, 'Color', [0 0.45 0.74]) %[output:15df5549]
quiver3(mu(1), mu(2), mu(3), pcAxisScale*V(1,3), pcAxisScale*V(2,3), pcAxisScale*V(3,3), ... %[output:15df5549]
    0, 'LineWidth', 2.2, 'Color', [0.47 0.67 0.19]) %[output:15df5549]
grid on %[output:15df5549]
axis equal %[output:15df5549]
xlim(axisLimits(:,1)') %[output:15df5549]
ylim(axisLimits(:,2)') %[output:15df5549]
zlim(axisLimits(:,3)') %[output:15df5549]
view(34,22) %[output:15df5549]
xlabel('Feature 1') %[output:15df5549]
ylabel('Feature 2') %[output:15df5549]
zlabel('Feature 3') %[output:15df5549]
title('Original 3-D feature space') %[output:15df5549]
legend('observations','PC1','PC2','PC3', 'Location', 'best') %[output:15df5549]

nexttile %[output:15df5549]
scatter3(scores(:,1), scores(:,2), scores(:,3), 22, plotColors, 'filled') %[output:15df5549]
grid on %[output:15df5549]
axis equal %[output:15df5549]
view(31,20) %[output:15df5549]
xlabel('PC 1 score') %[output:15df5549]
ylabel('PC 2 score') %[output:15df5549]
zlabel('PC 3 score') %[output:15df5549]
title('Coordinates in principal axes') %[output:15df5549]

nexttile %[output:15df5549]
scatter(rank2Scores(:,1), rank2Scores(:,2), 24, plotColors, 'filled') %[output:15df5549]
grid on %[output:15df5549]
axis equal %[output:15df5549]
xlabel('PC 1 score') %[output:15df5549]
ylabel('PC 2 score') %[output:15df5549]
title('Reduced 2-D feature space') %[output:15df5549]

%%
%[text] ## Explained Variance and Rank-2 Reconstruction
%[text] Because the data cloud is nearly planar, the first two singular values account for almost all of the variance.
%[text] Reconstructing from only the first two principal directions gives the best rank-2 approximation of the centered data in the least-squares sense.
rank2RetainedVariance = cumulativeExplained(2);
rank2RelativeError = norm(X - Xrank2, 'fro') / norm(Xc, 'fro');
reductionSummary = table(3, 2, rank2RetainedVariance, rank2RelativeError, ...
    'VariableNames', ["OriginalDimension","ReducedDimension","RetainedVariancePercent","RelativeFrobeniusError"]);

tiledlayout(1,2)

nexttile
yyaxis left
bar(1:3, explained, 0.55, 'FaceColor', [0.2 0.6 0.8], 'EdgeColor', 'none')
ylabel('Explained variance (%)')
ylim([0 110])
yyaxis right
plot(1:3, cumulativeExplained, '-o', 'Color', [0.85 0.33 0.10], 'LineWidth', 2, ...
    'MarkerFaceColor', [0.85 0.33 0.10])
ylabel('Cumulative variance (%)')
ylim([0 110])
grid on
xlabel('Principal component')
title('Variance captured by each component')

nexttile
scatter3(X(:,1), X(:,2), X(:,3), 16, plotColors, 'filled', ...
    'MarkerFaceAlpha', 0.25, 'MarkerEdgeAlpha', 0.25)
hold on
scatter3(Xrank2(:,1), Xrank2(:,2), Xrank2(:,3), 20, plotColors, 'filled')
grid on
axis equal
xlim(axisLimits(:,1)')
ylim(axisLimits(:,2)')
zlim(axisLimits(:,3)')
view(34,22)
xlabel('Feature 1')
ylabel('Feature 2')
zlabel('Feature 3')
title('Rank-2 reconstruction in the original space')
legend('original data','reconstructed from PC1 and PC2', 'Location', 'best')

%%
%[text] ## Key Takeaways
%[text] - Centering the data and taking its SVD gives the PCA directions directly through the columns of $V$.
%[text] - The principal-component coordinates are the columns of $U \\Sigma$.
%[text] - Keeping only the first two components turns this three-dimensional feature space into a two-dimensional one while preserving most of the variance for this synthetic example \
reductionSummary

function R = rotationFromEuler(axDeg, ayDeg, azDeg)
ax = deg2rad(axDeg);
ay = deg2rad(ayDeg);
az = deg2rad(azDeg);

Rx = [1 0 0; 0 cos(ax) -sin(ax); 0 sin(ax) cos(ax)];
Ry = [cos(ay) 0 sin(ay); 0 1 0; -sin(ay) 0 cos(ay)];
Rz = [cos(az) -sin(az) 0; sin(az) cos(az) 0; 0 0 1];

R = Rz * Ry * Rx;
end

function limits = paddedLimits(data, paddingFraction)
minimums = min(data, [], 1);
maximums = max(data, [], 1);
spans = maximums - minimums;
spans(spans == 0) = 1;
padding = paddingFraction * spans;
limits = [
    minimums - padding
    maximums + padding
];
end

